import React from 'react';
import styled from 'styled-components';
import { Link } from 'react-router-dom';
// Şimdilik diğer bileşenleri import etmeyi kaldıralım
// import Hero from '../components/home/Hero';
// import Features from '../components/home/Features';
// import PopularRecipes from '../components/home/PopularRecipes';
// import HowItWorks from '../components/home/HowItWorks';
// import Testimonials from '../components/home/Testimonials';
// import CallToAction from '../components/home/CallToAction';

// Styled components tanımlamaları
const HomeContainer = styled.div`
  max-width: 1200px;
  margin: 0 auto;
  padding: 20px;
`;

// Header için yeni styled components
const Header = styled.header`
  display: flex;
  justify-content: center;
  align-items: center;
  padding: 20px 0;
  margin-bottom: 20px;
`;

const Logo = styled.div`
  font-size: 2.2rem;
  font-weight: bold;
  color: #4CAF50;
  text-align: center;
  
  span {
    color: #FF9800;
  }
`;

const NavButtons = styled.div`
  display: flex;
  gap: 15px;
`;

const NavButton = styled(Link)`
  padding: 10px 20px;
  border-radius: 4px;
  text-decoration: none;
  font-weight: 500;
  
  &.primary {
    background-color: #4CAF50;
    color: white;
    
    &:hover {
      background-color: #45a049;
    }
  }
  
  &.secondary {
    background-color: transparent;
    color: #4CAF50;
    border: 1px solid #4CAF50;
    
    &:hover {
      background-color: rgba(76, 175, 80, 0.1);
    }
  }
`;

const HeroSection = styled.div`
  position: relative;
  background-color: #f8f9fa;
  background-image: url('https://images.unsplash.com/photo-1543353071-10c8ba85a904?ixlib=rb-1.2.1&auto=format&fit=crop&w=1350&q=80');
  background-size: cover;
  background-position: center;
  padding: 100px 20px;
  text-align: center;
  border-radius: 12px;
  margin-bottom: 60px;
  box-shadow: 0 5px 15px rgba(0, 0, 0, 0.15);
  overflow: hidden;
  
  &:before {
    content: '';
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background: linear-gradient(135deg, rgba(76, 175, 80, 0.85) 0%, rgba(255, 152, 0, 0.85) 100%);
    z-index: 1;
  }
  
  * {
    position: relative;
    z-index: 2;
  }
`;

const HeroTitle = styled.h1`
  color: white;
  font-size: 3.5rem;
  margin-bottom: 20px;
  text-shadow: 2px 2px 4px rgba(0, 0, 0, 0.2);
`;

const HeroSubtitle = styled.p`
  font-size: 1.4rem;
  color: white;
  max-width: 700px;
  margin: 0 auto 50px;
  line-height: 1.6;
  text-shadow: 1px 1px 2px rgba(0, 0, 0, 0.2);
`;

const SearchBar = styled.div`
  display: flex;
  max-width: 700px;
  margin: 0 auto;
  box-shadow: 0 5px 20px rgba(0, 0, 0, 0.2);
  border-radius: 8px;
  overflow: hidden;
  
  @media (max-width: 768px) {
    flex-direction: column;
    box-shadow: none;
  }
`;

const SearchInput = styled.input`
  flex: 1;
  padding: 20px 25px;
  border: none;
  font-size: 1.1rem;
  
  @media (max-width: 768px) {
    border-radius: 8px;
    margin-bottom: 10px;
    border: 1px solid #ddd;
  }
`;

const SearchButton = styled.button`
  background-color: #FF9800;
  color: white;
  border: none;
  padding: 20px 35px;
  cursor: pointer;
  font-weight: bold;
  font-size: 1.1rem;
  transition: all 0.3s ease;
  
  &:hover {
    background-color: #F57C00;
    transform: translateY(-2px);
  }
  
  @media (max-width: 768px) {
    border-radius: 8px;
    padding: 15px;
  }
`;

const SectionTitle = styled.h2`
  color: #333;
  font-size: 2.2rem;
  margin: 40px 0 30px;
  text-align: center;
  position: relative;
  
  &:after {
    content: '';
    display: block;
    width: 80px;
    height: 3px;
    background: linear-gradient(90deg, #4CAF50, #FF9800);
    margin: 15px auto;
    border-radius: 3px;
  }
`;

const CategoriesContainer = styled.div`
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 25px;
  margin-bottom: 70px;
  
  @media (max-width: 992px) {
    grid-template-columns: repeat(3, 1fr);
  }
  
  @media (max-width: 768px) {
    grid-template-columns: repeat(2, 1fr);
  }
  
  @media (max-width: 480px) {
    grid-template-columns: 1fr;
  }
`;

const CategoryCard = styled(Link)`
  background-color: white;
  border-radius: 12px;
  overflow: hidden;
  box-shadow: 0 3px 15px rgba(0, 0, 0, 0.1);
  transition: transform 0.3s ease, box-shadow 0.3s ease;
  cursor: pointer;
  position: relative;
  display: block;
  text-decoration: none;
  
  &:hover {
    transform: translateY(-10px);
    box-shadow: 0 15px 30px rgba(0, 0, 0, 0.15);
    
    img {
      transform: scale(1.08);
    }
  }
`;

const CategoryImage = styled.img`
  width: 100%;
  height: 180px;
  object-fit: cover;
  transition: transform 0.5s ease;
`;

const CategoryContent = styled.div`
  padding: 20px;
  text-align: center;
  background: white;
`;

const CategoryTitle = styled.h3`
  margin-bottom: 10px;
  color: #333;
  font-weight: 600;
`;

const CategoryCount = styled.span`
  color: #777;
  font-size: 0.95rem;
  background-color: #f8f9fa;
  padding: 5px 12px;
  border-radius: 20px;
  display: inline-block;
`;

const FeaturedRecipesContainer = styled.div`
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 30px;
  margin-bottom: 70px;
  
  @media (max-width: 992px) {
    grid-template-columns: repeat(2, 1fr);
  }
  
  @media (max-width: 640px) {
    grid-template-columns: 1fr;
  }
`;

const RecipeCard = styled.div`
  background-color: white;
  border-radius: 12px;
  overflow: hidden;
  box-shadow: 0 3px 15px rgba(0, 0, 0, 0.1);
  transition: all 0.3s ease;
  
  &:hover {
    transform: translateY(-10px);
    box-shadow: 0 15px 30px rgba(0, 0, 0, 0.15);
    
    img {
      transform: scale(1.08);
    }
  }
`;

const RecipeImage = styled.img`
  width: 100%;
  height: 220px;
  object-fit: cover;
  transition: transform 0.5s ease;
`;

const RecipeContent = styled.div`
  padding: 25px;
`;

const RecipeTitle = styled.h3`
  color: #333;
  margin-bottom: 10px;
  font-size: 1.3rem;
`;

const RecipeMeta = styled.div`
  display: flex;
  gap: 15px;
  margin-bottom: 15px;
  color: #666;
  font-size: 0.9rem;
  
  span {
    display: flex;
    align-items: center;
    gap: 5px;
  }
`;

const RecipeDescription = styled.p`
  color: #666;
  margin-bottom: 20px;
  display: -webkit-box;
  -webkit-line-clamp: 3;
  -webkit-box-orient: vertical;
  overflow: hidden;
`;

const RecipePrice = styled.div`
  font-weight: bold;
  color: #4CAF50;
  font-size: 1.1rem;
  margin-top: 15px;
  padding-top: 15px;
  border-top: 1px solid #f0f0f0;
`;

const ViewRecipeButton = styled(Link)`
  display: block;
  background-color: #4CAF50;
  color: white;
  text-align: center;
  text-decoration: none;
  padding: 12px 0;
  border-radius: 6px;
  font-weight: 600;
  margin-top: 15px;
  transition: all 0.3s ease;
  
  &:hover {
    background-color: #45a049;
    transform: translateY(-3px);
  }
`;

const HowItWorksContainer = styled.div`
  margin-bottom: 80px;
`;

const StepsContainer = styled.div`
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 30px;
  
  @media (max-width: 768px) {
    grid-template-columns: 1fr;
  }
`;

const StepCard = styled.div`
  text-align: center;
  padding: 40px 30px;
  background-color: white;
  border-radius: 12px;
  box-shadow: 0 3px 15px rgba(0, 0, 0, 0.1);
  transition: transform 0.3s ease;
  
  &:hover {
    transform: translateY(-10px);
  }
`;

const StepIcon = styled.div`
  width: 100px;
  height: 100px;
  background: linear-gradient(135deg, #4CAF50, #8BC34A);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto 25px;
  color: white;
  font-size: 2.5rem;
  font-weight: bold;
`;

const StepTitle = styled.h3`
  color: #333;
  margin-bottom: 15px;
  font-size: 1.4rem;
`;

const StepDescription = styled.p`
  color: #666;
  line-height: 1.6;
`;

const TipsContainer = styled.div`
  margin-bottom: 80px;
  background-color: #f9f9f9;
  padding: 40px;
  border-radius: 12px;
  box-shadow: 0 3px 15px rgba(0, 0, 0, 0.05);
`;

const TipsGrid = styled.div`
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 30px;
  
  @media (max-width: 768px) {
    grid-template-columns: 1fr;
  }
`;

const TipCard = styled.div`
  display: flex;
  align-items: flex-start;
  background: white;
  padding: 25px;
  border-radius: 10px;
  box-shadow: 0 3px 10px rgba(0, 0, 0, 0.05);
  
  &:hover {
    box-shadow: 0 5px 15px rgba(0, 0, 0, 0.1);
  }
`;

const TipIcon = styled.div`
  min-width: 50px;
  height: 50px;
  background: linear-gradient(135deg, #FF9800, #FFC107);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-right: 20px;
  color: white;
  font-size: 1.5rem;
  font-weight: bold;
`;

const TipContent = styled.div``;

const TipTitle = styled.h4`
  color: #333;
  margin-bottom: 10px;
  font-size: 1.2rem;
`;

const TipText = styled.p`
  color: #666;
  line-height: 1.5;
`;

const NewsletterSection = styled.div`
  background: linear-gradient(135deg, #4CAF50, #8BC34A);
  padding: 60px 40px;
  border-radius: 12px;
  text-align: center;
  margin-bottom: 80px;
`;

const NewsletterTitle = styled.h2`
  color: white;
  font-size: 2.2rem;
  margin-bottom: 20px;
`;

const NewsletterText = styled.p`
  color: rgba(255, 255, 255, 0.9);
  font-size: 1.1rem;
  max-width: 700px;
  margin: 0 auto 30px;
  line-height: 1.6;
`;

const NewsletterForm = styled.form`
  display: flex;
  max-width: 600px;
  margin: 0 auto;
  border-radius: 8px;
  overflow: hidden;
  
  @media (max-width: 768px) {
    flex-direction: column;
  }
`;

const NewsletterInput = styled.input`
  flex: 1;
  padding: 15px 20px;
  border: none;
  font-size: 1rem;
  
  @media (max-width: 768px) {
    margin-bottom: 10px;
    border-radius: 8px;
  }
`;

const NewsletterButton = styled.button`
  background-color: #FF9800;
  color: white;
  border: none;
  padding: 15px 30px;
  cursor: pointer;
  font-weight: bold;
  font-size: 1rem;
  transition: all 0.3s ease;
  
  &:hover {
    background-color: #F57C00;
  }
  
  @media (max-width: 768px) {
    border-radius: 8px;
  }
`;

// HomePage bileşeni
const HomePage = () => {
  // Kategoriler
  const categories = [
    {
      id: 'ana-yemekler',
      title: 'Ana Yemekler',
      count: 42,
      image: 'https://images.unsplash.com/photo-1518779578993-ec3579fee39f?ixlib=rb-1.2.1&auto=format&fit=crop&w=1350&q=80'
    },
    {
      id: 'corbalar',
      title: 'Çorbalar',
      count: 18,
